package org.jtorch.opgen;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.stream.Stream;
import org.jtorch.json.Json;

/**
 * Deterministic generator for JTorch operator metadata.
 *
 * <p>Inputs live under {@code schema/ops}. Outputs are checked in and regenerated by {@code ./gradlew
 * regenerateSchemas}; {@code verifyGeneratedClean} fails the build when checked-in outputs drift.
 */
public final class Main {
    private static final Set<String> STATUSES =
            Set.of("unsupported", "schema-only", "forward", "autograd", "full-semantics", "compiled", "distributed", "deprecated");

    private Main() {}

    public static void main(String[] args) throws IOException {
        boolean check = false;
        Path root = null;
        for (int i = 0; i < args.length; i++) {
            switch (args[i]) {
                case "--check" -> check = true;
                case "--root" -> root = Path.of(args[++i]).toAbsolutePath().normalize();
                default -> throw new IllegalArgumentException("Unknown argument: " + args[i]);
            }
        }
        if (root == null) {
            throw new IllegalArgumentException("--root is required");
        }
        List<Schema> schemas = loadSchemas(root.resolve("schema/ops"));
        Map<Path, String> outputs = render(root, schemas);

        boolean changed = false;
        for (Map.Entry<Path, String> entry : outputs.entrySet()) {
            Path target = entry.getKey();
            String expected = entry.getValue();
            if (check) {
                String actual = Files.exists(target) ? Files.readString(target, StandardCharsets.UTF_8) : "";
                if (!actual.equals(expected)) {
                    System.err.println("Generated file is stale: " + root.relativize(target));
                    changed = true;
                }
            } else {
                String previous = Files.exists(target) ? Files.readString(target, StandardCharsets.UTF_8) : null;
                if (!expected.equals(previous)) {
                    Files.createDirectories(target.getParent());
                    Files.writeString(target, expected, StandardCharsets.UTF_8);
                    System.out.println("Wrote " + root.relativize(target));
                }
            }
        }
        if (check) {
            if (changed) {
                System.err.println("Run ./gradlew regenerateSchemas and commit the result.");
                System.exit(1);
            }
            System.out.println("Generated sources are up to date (" + schemas.size() + " operators).");
        } else {
            System.out.println("Schema generation complete (" + schemas.size() + " operators).");
        }
    }

    private static List<Schema> loadSchemas(Path directory) throws IOException {
        List<Schema> schemas = new ArrayList<>();
        try (Stream<Path> files = Files.list(directory)) {
            for (Path file : files.filter(path -> path.toString().endsWith(".json")).sorted().toList()) {
                Map<String, Object> document = Json.parseObject(Files.readString(file, StandardCharsets.UTF_8));
                if (Json.intValue(Json.require(document, "schemaVersion")) != 1) {
                    throw new IllegalArgumentException("Unsupported schema version in " + file);
                }
                String namespace = Json.string(Json.require(document, "namespace"));
                for (Object raw : Json.array(Json.require(document, "operators"))) {
                    schemas.add(parseOperator(namespace, Json.object(raw), file));
                }
            }
        }
        Set<String> fullNames = new LinkedHashSet<>();
        Set<String> constants = new LinkedHashSet<>();
        for (Schema schema : schemas) {
            if (!fullNames.add(schema.fullName())) {
                throw new IllegalArgumentException("Duplicate operator " + schema.fullName());
            }
            if (!constants.add(schema.constant())) {
                throw new IllegalArgumentException("Duplicate generated constant " + schema.constant());
            }
        }
        schemas.sort((left, right) -> left.fullName().compareTo(right.fullName()));
        return List.copyOf(schemas);
    }

    private static Schema parseOperator(String namespace, Map<String, Object> raw, Path file) {
        String name = Json.string(Json.require(raw, "name"));
        String overload = Json.string(Json.require(raw, "overload"));
        List<Arg> arguments = new ArrayList<>();
        for (Object argValue : Json.array(Json.require(raw, "args"))) {
            Map<String, Object> arg = Json.object(argValue);
            arguments.add(new Arg(
                    Json.string(Json.require(arg, "name")),
                    Json.string(Json.require(arg, "type")),
                    arg.containsKey("default") ? Json.string(Json.require(arg, "default")) : null,
                    arg.containsKey("keywordOnly") && Json.booleanValue(Json.require(arg, "keywordOnly"))));
        }
        List<String> returns = new ArrayList<>();
        for (Object value : Json.array(Json.require(raw, "returns"))) {
            returns.add(Json.string(value));
        }
        boolean differentiable = Json.booleanValue(Json.require(raw, "differentiable"));
        boolean composite = raw.containsKey("composite") && Json.booleanValue(Json.require(raw, "composite"));
        boolean internal = raw.containsKey("internal") && Json.booleanValue(Json.require(raw, "internal"));
        if (composite && !differentiable) {
            throw new IllegalArgumentException("Composite operator must be differentiable: " + name + " in " + file);
        }
        String reverse = raw.containsKey("reverse") ? Json.string(Json.require(raw, "reverse")) : null;
        if (differentiable && reverse == null) {
            throw new IllegalArgumentException("Differentiable operator needs a reverse formula: " + name + " in " + file);
        }
        String status = Json.string(Json.require(raw, "status"));
        if (!STATUSES.contains(status)) {
            throw new IllegalArgumentException("Unknown status '" + status + "' for " + name + " in " + file);
        }
        List<String> variants = new ArrayList<>();
        for (Object value : Json.array(Json.require(raw, "variants"))) {
            variants.add(Json.string(value));
        }
        String summary = Json.string(Json.require(raw, "summary"));
        return new Schema(
                namespace,
                name,
                overload,
                namespace + "::" + name + "." + overload,
                constant(name, overload),
                List.copyOf(arguments),
                List.copyOf(returns),
                differentiable,
                reverse,
                List.copyOf(variants),
                composite,
                internal,
                status,
                summary);
    }

    private static String constant(String name, String overload) {
        StringBuilder out = new StringBuilder();
        appendConstant(out, name);
        if (!overload.equals("default")) {
            out.append('_');
            appendConstant(out, overload);
        }
        return out.toString();
    }

    private static void appendConstant(StringBuilder out, String value) {
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            if (Character.isLetterOrDigit(ch)) {
                out.append(Character.toUpperCase(ch));
            } else if (ch != '.' && (out.isEmpty() || out.charAt(out.length() - 1) != '_')) {
                out.append('_');
            }
        }
    }

    private static Map<Path, String> render(Path root, List<Schema> schemas) {
        Map<Path, String> outputs = new LinkedHashMap<>();
        Path generated = root.resolve("modules/jtorch-generated/src/main/java/org/jtorch/core/generated");
        outputs.put(generated.resolve("Ops.java"), renderOps(schemas));
        outputs.put(generated.resolve("Schemas.java"), renderSchemas(schemas));
        outputs.put(
                root.resolve("modules/jtorch-core/src/main/java/org/jtorch/core/OpRegistry.java"),
                renderOpRegistry(schemas));
        outputs.put(root.resolve("docs/OPERATORS.md"), renderDocs(schemas));
        outputs.put(root.resolve("compat/operators.json"), renderLedger(schemas));
        outputs.put(root.resolve("compat/reports/operators.md"), renderReport(schemas));
        outputs.put(
                root.resolve("tests/parity/src/test/generated/java/org/jtorch/parity/GeneratedCases.java"),
                renderCases(schemas));
        return outputs;
    }

    private static String renderOps(List<Schema> schemas) {
        StringBuilder out = new StringBuilder();
        out.append("// Generated by tools/opgen from schema/ops. DO NOT EDIT.\n");
        out.append("package org.jtorch.core.generated;\n\n");
        out.append("/** Operator identifiers generated from the canonical JTorch schema. */\n");
        out.append("public final class Ops {\n");
        out.append("    private Ops() {}\n\n");
        for (Schema schema : schemas) {
            out.append("    public static final String ")
                    .append(schema.constant())
                    .append(" = \"")
                    .append(schema.fullName())
                    .append("\";\n");
        }
        out.append("}\n");
        return out.toString();
    }

    private static String renderSchemas(List<Schema> schemas) {
        StringBuilder out = new StringBuilder();
        out.append("// Generated by tools/opgen from schema/ops. DO NOT EDIT.\n");
        out.append("package org.jtorch.core.generated;\n\n");
        out.append("import java.util.List;\n");
        out.append("import java.util.Map;\n");
        out.append("import java.util.function.Function;\n");
        out.append("import java.util.stream.Collectors;\n\n");
        out.append("/** Canonical operator metadata generated from schema/ops. */\n");
        out.append("public final class Schemas {\n");
        out.append("    private Schemas() {}\n\n");
        out.append("    /** One declared operator argument. */\n");
        out.append("    public record Arg(String name, String type, String defaultValue, boolean keywordOnly) {}\n\n");
        out.append("    /** One canonical operator schema. */\n");
        out.append("    public record Schema(\n");
        out.append("            String namespace,\n");
        out.append("            String opName,\n");
        out.append("            String overload,\n");
        out.append("            String fullName,\n");
        out.append("            List<Arg> args,\n");
        out.append("            List<String> returns,\n");
        out.append("            boolean differentiable,\n");
        out.append("            String reverse,\n");
        out.append("            List<String> variants,\n");
        out.append("            boolean composite,\n");
        out.append("            boolean internal,\n");
        out.append("            String status,\n");
        out.append("            String summary) {}\n\n");
        out.append("    public static final List<Schema> ALL = List.of(\n");
        for (int i = 0; i < schemas.size(); i++) {
            Schema schema = schemas.get(i);
            out.append("            new Schema(\n");
            out.append("                    \"").append(escape(schema.namespace())).append("\",\n");
            out.append("                    \"").append(escape(schema.opName())).append("\",\n");
            out.append("                    \"").append(escape(schema.overload())).append("\",\n");
            out.append("                    \"").append(escape(schema.fullName())).append("\",\n");
            out.append("                    List.of(\n");
            for (int j = 0; j < schema.args().size(); j++) {
                Arg arg = schema.args().get(j);
                out.append("                            new Arg(")
                        .append(quote(arg.name())).append(", ")
                        .append(quote(arg.type())).append(", ")
                        .append(arg.defaultValue() == null ? "null" : quote(arg.defaultValue())).append(", ")
                        .append(arg.keywordOnly()).append(")")
                        .append(j + 1 < schema.args().size() ? ",\n" : "\n");
            }
            out.append("                    ),\n");
            out.append("                    List.of(");
            for (int j = 0; j < schema.returns().size(); j++) {
                if (j > 0) {
                    out.append(", ");
                }
                out.append(quote(schema.returns().get(j)));
            }
            out.append("),\n");
            out.append("                    ").append(schema.differentiable()).append(",\n");
            out.append("                    ").append(schema.reverse() == null ? "null" : quote(schema.reverse())).append(",\n");
            out.append("                    List.of(");
            for (int j = 0; j < schema.variants().size(); j++) {
                if (j > 0) {
                    out.append(", ");
                }
                out.append(quote(schema.variants().get(j)));
            }
            out.append("),\n");
            out.append("                    ").append(schema.composite()).append(",\n");
            out.append("                    ").append(schema.internal()).append(",\n");
            out.append("                    ").append(quote(schema.status())).append(",\n");
            out.append("                    ").append(quote(schema.summary())).append(")");
            out.append(i + 1 < schemas.size() ? ",\n" : "\n");
        }
        out.append("    );\n\n");
        out.append("    private static final Map<String, Schema> BY_NAME =\n");
        out.append("            ALL.stream().collect(Collectors.toUnmodifiableMap(Schema::fullName, Function.identity()));\n\n");
        out.append("    public static Schema get(String fullName) {\n");
        out.append("        Schema schema = BY_NAME.get(fullName);\n");
        out.append("        if (schema == null) {\n");
        out.append("            throw new IllegalArgumentException(\"Unknown operator schema: \" + fullName);\n");
        out.append("        }\n");
        out.append("        return schema;\n");
        out.append("    }\n");
        out.append("}\n");
        return out.toString();
    }

    private static String renderOpRegistry(List<Schema> schemas) {
        StringBuilder out = new StringBuilder();
        out.append("// Generated by tools/opgen from schema/ops. DO NOT EDIT.\n");
        out.append("package org.jtorch.core;\n\n");
        out.append("import org.jtorch.core.generated.Ops;\n\n");
        out.append("/** Typed operator handles generated from the canonical schema. */\n");
        out.append("public final class OpRegistry {\n");
        out.append("    private OpRegistry() {}\n\n");
        for (Schema schema : schemas) {
            out.append("    public static final Op ")
                    .append(schema.constant())
                    .append(" = Op.of(Ops.")
                    .append(schema.constant())
                    .append(");\n");
        }
        out.append("}\n");
        return out.toString();
    }

    private static String renderDocs(List<Schema> schemas) {
        StringBuilder out = new StringBuilder();
        out.append("# Operators\n\n");
        out.append("Generated by `tools/opgen` from `schema/ops`. Do not edit by hand; run\n");
        out.append("`./gradlew regenerateSchemas`. Status values follow the compatibility ledger vocabulary in `docs/DESIGN.md` §2.\n\n");
        out.append("| Operator | Status | Differentiable | Arguments | Summary |\n");
        out.append("| --- | --- | --- | --- | --- |\n");
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            List<String> arguments = new ArrayList<>();
            for (Arg arg : schema.args()) {
                StringBuilder text = new StringBuilder(arg.name()).append(": ").append(arg.type());
                if (arg.defaultValue() != null) {
                    text.append(" = ").append(arg.defaultValue());
                }
                arguments.add(text.toString());
            }
            out.append("| `")
                    .append(schema.fullName())
                    .append("` | ")
                    .append(schema.status())
                    .append(" | ")
                    .append(schema.differentiable() ? "yes" : "no")
                    .append(" | ")
                    .append(String.join(", ", arguments).replace("|", "\\|"))
                    .append(" | ")
                    .append(schema.summary().replace("|", "\\|"))
                    .append(" |\n");
        }
        return out.toString();
    }

    private static String renderLedger(List<Schema> schemas) {
        Map<String, Integer> counts = new TreeMap<>();
        List<Object> entries = new ArrayList<>();
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            counts.merge(schema.status(), 1, Integer::sum);
            Map<String, Object> entry = new LinkedHashMap<>();
            entry.put("name", schema.fullName());
            entry.put("status", schema.status());
            entry.put("differentiable", schema.differentiable());
            entry.put("reverse", schema.reverse());
            entries.add(entry);
        }
        Map<String, Object> ledger = new LinkedHashMap<>();
        ledger.put("generatedFrom", "schema/ops");
        ledger.put("total", entries.size());
        ledger.put("byStatus", counts);
        ledger.put("operators", entries);
        return Json.writePretty(ledger) + "\n";
    }

    private static String renderReport(List<Schema> schemas) {
        Map<String, Integer> counts = new TreeMap<>();
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            counts.merge(schema.status(), 1, Integer::sum);
        }
        StringBuilder out = new StringBuilder();
        out.append("# Operator coverage\n\n");
        out.append("Generated by `tools/opgen` from `schema/ops`. These are declared statuses, not test\n");
        out.append("results; differential results live in the parity suite. No percentage is claimed.\n\n");
        out.append("| Status | Operators |\n| --- | --- |\n");
        counts.forEach((status, count) -> out.append("| ").append(status).append(" | ").append(count).append(" |\n"));
        out.append("\n## Declared operators\n\n");
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            out.append("- `").append(schema.fullName()).append("` — ").append(schema.status());
            if (schema.composite()) {
                out.append(" (composite)");
            }
            out.append('\n');
        }
        return out.toString();
    }

    private static String renderCases(List<Schema> schemas) {
        StringBuilder out = new StringBuilder();
        out.append("// Generated by tools/opgen from schema/ops. DO NOT EDIT.\n");
        out.append("package org.jtorch.parity;\n\n");
        out.append("import java.util.List;\n\n");
        out.append("/** Parity case descriptors generated from the canonical schema. */\n");
        out.append("public final class GeneratedCases {\n");
        out.append("    private GeneratedCases() {}\n\n");
        out.append("    /** One golden-fixture descriptor. */\n");
        out.append("    public record Case(String operator, String status, boolean differentiable, String fixture) {}\n\n");
        out.append("    public static final List<Case> ALL = List.of(\n");
        int generated = 0;
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            generated++;
        }
        int emitted = 0;
        for (Schema schema : schemas) {
            if (schema.internal()) {
                continue;
            }
            String slug = schema.fullName().substring(schema.fullName().indexOf("::") + 2);
            out.append("            new Case(")
                    .append(quote(schema.fullName())).append(", ")
                    .append(quote(schema.status())).append(", ")
                    .append(schema.differentiable()).append(", ")
                    .append(quote(slug))
                    .append(")")
                    .append(++emitted < generated ? ",\n" : "\n");
        }
        out.append("    );\n");
        out.append("}\n");
        return out.toString();
    }

    private static String quote(String value) {
        return "\"" + escape(value) + "\"";
    }

    private static String escape(String value) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            switch (ch) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> out.append(ch);
            }
        }
        return out.toString();
    }

    private record Arg(String name, String type, String defaultValue, boolean keywordOnly) {}

    private record Schema(
            String namespace,
            String opName,
            String overload,
            String fullName,
            String constant,
            List<Arg> args,
            List<String> returns,
            boolean differentiable,
            String reverse,
            List<String> variants,
            boolean composite,
            boolean internal,
            String status,
            String summary) {}
}
